{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "An earlier observed failure is followed by a subsequent agent action intended to resolve that failure (e.g., installing a missing or incompatible dependency, or otherwise correcting the blocked condition).",
      "source_description": "An earlier observed execution failure or error condition reported by a tool.",
      "target_description": "A subsequent agent action whose purpose is to resolve that failure."
    },
    {
      "name": "INVESTIGATES_FAILURE_CAUSE",
      "definition": "An earlier observed failure is followed by a diagnostic action that gathers additional information (version, log, environment state) in order to determine why the failure occurred before further repair attempts.",
      "source_description": "An earlier observed execution failure whose cause is not yet understood.",
      "target_description": "A subsequent diagnostic action that inspects environment or tool state to explain the failure."
    },
    {
      "name": "PROBES_ENVIRONMENT_FOR_ALTERNATIVE_CAPABILITY",
      "definition": "After observing that a required tool, library, or runtime is unavailable, the agent issues an action to enumerate or test alternative available tools, runtimes, or packages that could accomplish the task.",
      "source_description": "An observation that the initially expected tool, library, or runtime is missing or unusable.",
      "target_description": "A subsequent exploratory action that checks for or lists alternative available capabilities."
    },
    {
      "name": "VERIFIES_DEPENDENCY_AVAILABILITY_BEFORE_USE",
      "definition": "A decision to rely on a specific library or tool is followed by an explicit action that checks whether that dependency is actually installed and loadable, prior to using it in the workflow.",
      "source_description": "An agent decision to use a particular library, package, or tool as part of the plan.",
      "target_description": "A subsequent query that confirms whether that dependency is present in the environment."
    },
    {
      "name": "MONITORS_ASYNC_LONG_RUNNING_OPERATION",
      "definition": "An action that launches a long-running or asynchronous operation (such as a package build or installation) is followed by a separate action that waits for and inspects the progress or completion status of that operation.",
      "source_description": "An agent action that starts a long-running or background operation.",
      "target_description": "A subsequent action that polls or inspects the status/output of that operation."
    },
    {
      "name": "SWITCHES_STRATEGY_DUE_TO_OBSERVED_CONSTRAINT",
      "definition": "An observation that a planned approach is blocked or constrained by the environment (for example a package manager refusing installation) is followed by an action that abandons that approach and adopts a different tooling or execution path consistent with the constraint.",
      "source_description": "An observation reporting an environmental constraint or prohibition that blocks the previously planned approach.",
      "target_description": "A subsequent agent action adopting an alternative approach that respects the observed constraint."
    }
  ]
}

